// ===== Configuração (preencha no seu n8n; nunca no repositório) =====
const URL_VALIDACAO = 'https://exemplo.com/webhook/validar';  // endereço público da validação
const MODELO_CERTIFICADO = '';  // ID do modelo no Google Slides
const MODELO_DECLARACAO = '';
const MODELO_CERTIFICADO_CURSO = '';  // duas páginas: certificado e conteúdo programático
// Opcional: IDs (no Slides) das duas caixas de conteúdo do modelo de curso, para os
// títulos de semestre saírem em negrito e na COR_TITULOS; vazio, saem em maiúsculas.
const CAIXAS_CONTEUDO = [];
const COR_TITULOS = '#0f3d3e';
const URL_QR = 'https://exemplo.com/webhook/qr';  // endereço público do fluxo "QR code de validação"
// ponytail: o ZIP é montado dentro da requisição; acima de uns 15 PDFs a conexão
// pode cair por tempo. Ajustar depois de medir no ambiente.
const LIMITE_ZIP = 15;
const LIMITE_CSV = 100;         // linhas por arquivo CSV
// ====================================================================

// Decide o que fazer com o pedido e devolve só dados; o HTML das telas fica nos
// subfluxos de tela (valores de texto já escapados aqui).
const TIPOS = {
  certificado_curso: 'Certificado de conclusão de curso',
  certificado_semestre: 'Certificado de conclusão de semestre',
  certificado_trimestre: 'Certificado de conclusão de trimestre',
  declaracao_matricula: 'Declaração de matrícula',
  declaracao_termino_semestre: 'Declaração de término de semestre',
};
const OBRIGATORIOS = {
  certificado_curso: ['nome', 'curso', 'carga_horaria'],
  certificado_semestre: ['nome', 'curso', 'carga_horaria'],
  certificado_trimestre: ['nome', 'curso', 'carga_horaria'],
  declaracao_matricula: ['nome', 'curso', 'cpf', 'rg', 'endereco'],
  declaracao_termino_semestre: ['nome', 'curso', 'cpf', 'rg', 'endereco'],
};
const CAMPOS = { nome: 'nome', curso: 'curso', carga_horaria: 'carga horária', data_emissao: 'data de emissão',
  cpf: 'CPF', rg: 'RG', endereco: 'endereço', dia_aula: 'dia de aula' };
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho',
  'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

const esc = v => String(v ?? '').replace(/[&<>"']/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const txt = v => String(v ?? '').trim();
const chave = v => txt(v).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[\s-]+/g, '_');
const ID = /^[A-Za-z0-9]{12}$/;
const dois = n => String(n).padStart(2, '0');

function data(valor) {  // 'AAAA-MM-DD' ou 'DD/MM/AAAA' -> {d, m, a}, ou null
  let x = txt(valor).match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const [a, m, d] = x ? [+x[1], +x[2], +x[3]]
    : (x = txt(valor).match(/^(\d{2})\/(\d{2})\/(\d{4})$/)) ? [+x[3], +x[2], +x[1]] : [];
  const dt = new Date(Date.UTC(a, m - 1, d));
  return x && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d ? { d, m, a } : null;
}

const pedido = $('Autorizar (subfluxo)').first().json;
const q = pedido.query || {};
const corpo = pedido.body || {};
let csv = '';
try { csv = String($('Ler CSV').first().json.csv_texto || ''); } catch (e) { /* sem arquivo CSV */ }
// IDs novos: 12 letras ou dígitos por vez, tirados da sequência aleatória do nó Crypto.
const aleatorios = txt($('Gerar ID').first().json.novo_id).replace(/[^A-Za-z0-9]/g, '');
const entrada = $input.all().map(i => i.json);
// Conteúdo programático (curso | semestre | item), só para o certificado de curso.
let conteudos = [];
try { conteudos = $('Conteúdo dos cursos').all().map(i => i.json); } catch (e) { /* nó não executado */ }
const linhas = entrada.filter(r => r.row_number);
const contagem = {};
for (const r of linhas) contagem[txt(r.id)] = (contagem[txt(r.id)] || 0) + 1;
let usados = 0;
function novoId() {
  const id = aleatorios.slice(usados * 12, ++usados * 12);
  return ID.test(id) && !contagem[id] ? (contagem[id] = 1, id) : null;
}

function problema(r) {
  if (!txt(r.id)) return '';
  if (!ID.test(txt(r.id))) return 'ID inválido';
  return contagem[txt(r.id)] > 1 ? 'ID duplicado' : '';
}
const base = { acao: 'pagina', email: esc(pedido.email) };
const partes = (ids, n) => Array.from({ length: Math.ceil(ids.length / n) }, (_, i) => ids.slice(i * n, (i + 1) * n));

function lista(status, erro, extra = {}) {
  const docs = linhas.slice().reverse().map(r => ({
    nome: esc(r.nome), tipo: esc(TIPOS[txt(r.tipo_documento)] || r.tipo_documento), curso: esc(r.curso),
    data: esc(r.data_emissao), status: esc(r.status), ativo: txt(r.status).toLowerCase() === 'ativo',
    problema: esc(problema(r)), id: problema(r) || !txt(r.id) ? '' : esc(txt(r.id)),
    href: esc('?' + (txt(r.id) ? 'id=' + encodeURIComponent(txt(r.id)) : 'linha=' + r.row_number)),
  }));
  return [{ json: { ...base, tela: 'lista', status, erro, docs, limite_zip: LIMITE_ZIP, ...extra } }];
}

// Hoje em Brasília (UTC-3, sem horário de verão desde 2019), para a data padrão do formulário.
const hoje = new Date(Date.now() - 3 * 3600000).toISOString().slice(0, 10);
function formulario(status, erro, valores) {
  const tipos = Object.keys(OBRIGATORIOS).map(v => ({ valor: v, nome: TIPOS[v] }));
  const val = {};
  for (const k of ['tipo_documento', ...Object.keys(CAMPOS)]) val[k] = esc(valores[k]);
  return [{ json: { ...base, tela: 'formulario', status, erro, tipos, valores: val } }];
}
function importar(status, erro) {
  return [{ json: { ...base, tela: 'importar', status, erro, limite_csv: LIMITE_CSV } }];
}

// Confere um documento novo (formulário ou linha do CSV); devolve a linha da planilha ou o erro.
function conferir(v) {
  const tipo = v.tipo_documento;
  if (!OBRIGATORIOS[tipo]) return { erro: 'escolha um tipo de documento válido' };
  const faltando = ['data_emissao', ...OBRIGATORIOS[tipo]].filter(k => !v[k]);
  if (faltando.length) return { erro: `preencha ${faltando.map(k => CAMPOS[k]).join(', ')}` };
  const d = data(v.data_emissao);
  if (!d) return { erro: 'data de emissão inválida (use DD/MM/AAAA)' };
  if (v.carga_horaria && !/^\d{1,4}$/.test(v.carga_horaria)) return { erro: 'carga horária: só números (horas)' };
  const id = novoId();
  if (!id) return { erro: 'falha ao gerar o ID; tente de novo' };
  const decl = tipo.startsWith('declaracao_');
  return { linha: { id, tipo_documento: tipo, nome: v.nome, curso: v.curso, carga_horaria: v.carga_horaria,
    data_emissao: `${dois(d.d)}/${dois(d.m)}/${d.a}`, status: 'ativo', cpf: decl ? v.cpf : '', rg: decl ? v.rg : '',
    endereco: decl ? v.endereco : '', dia_aula: decl ? v.dia_aula : '' } };
}

// CSV: separador ";" (Excel em português), "," ou tabulação; aspas como no padrão.
function lerCsv(texto) {
  texto = texto.replace(/^﻿/, '');
  const primeira = texto.split(/\r?\n/)[0] || '';
  const sep = [';', ',', '\t'].sort((a, b) => primeira.split(b).length - primeira.split(a).length)[0];
  const tabela = [];
  let linha = [], campo = '', aspas = false;
  for (let i = 0; i < texto.length; i++) {
    const c = texto[i];
    if (aspas) {
      if (c === '"' && texto[i + 1] === '"') { campo += '"'; i++; } else if (c === '"') aspas = false; else campo += c;
    } else if (c === '"') aspas = true;
    else if (c === sep) { linha.push(campo); campo = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && texto[i + 1] === '\n') i++;
      linha.push(campo); tabela.push(linha); linha = []; campo = '';
    } else campo += c;
  }
  if (campo || linha.length) { linha.push(campo); tabela.push(linha); }
  return tabela.filter(l => l.some(c => txt(c)));
}
const SINONIMOS = { tipo: 'tipo_documento', tipo_de_documento: 'tipo_documento', documento: 'tipo_documento',
  nome_completo: 'nome', aluno: 'nome', data: 'data_emissao', data_de_emissao: 'data_emissao',
  carga: 'carga_horaria', horas: 'carga_horaria', dia_de_aula: 'dia_aula' };
const TIPO_POR_NOME = {};
for (const [k, v] of Object.entries(TIPOS)) { TIPO_POR_NOME[k] = k; TIPO_POR_NOME[chave(v)] = k; }

if (entrada.some(r => r.error) || conteudos.some(r => r.error)) return lista(503, 'Não foi possível ler a planilha agora. Tente de novo em alguns minutos.');

// Vários documentos por CSV: tudo ou nada. Com erro em alguma linha, nada é gravado.
if (corpo.lote !== undefined) {
  if (!csv) return importar(422, 'Escolha um arquivo CSV.');
  const [cab = [], ...resto] = lerCsv(csv);
  const cols = cab.map(c => SINONIMOS[chave(c)] || chave(c));
  if (!cols.includes('tipo_documento') || !cols.includes('nome')) {
    return importar(422, 'O CSV precisa de uma primeira linha com os nomes das colunas (use o modelo).');
  }
  if (!resto.length) return importar(422, 'O CSV não tem nenhum documento.');
  if (resto.length > LIMITE_CSV) return importar(422, `Mande no máximo ${LIMITE_CSV} documentos por arquivo.`);
  const novos = [], erros = [];
  resto.forEach((l, i) => {
    const v = {};
    cols.forEach((c, j) => { v[c] = txt(l[j]).slice(0, 200); });
    v.tipo_documento = TIPO_POR_NOME[chave(v.tipo_documento)] || v.tipo_documento;
    v.carga_horaria = txt(v.carga_horaria).replace(/\s*(h|horas?)$/i, '');
    const r = conferir(v);
    if (r.erro) erros.push(`Linha ${i + 2}${v.nome ? ' (' + v.nome + ')' : ''}: ${r.erro}.`); else novos.push(r.linha);
  });
  if (erros.length) {
    return importar(422, 'Nada foi gravado. Corrija o CSV e envie de novo:<br>' + erros.slice(0, 20).map(esc).join('<br>')
      + (erros.length > 20 ? `<br>… e mais ${erros.length - 20} linhas com erro.` : ''));
  }
  return novos.map(linha => ({ json: { acao: 'cadastrar', linha,
    location: '?lote=' + novos.map(n => n.id).join(',') } }));
}

// Um documento novo pelo formulário: grava a linha e volta para a lista.
if (corpo.tipo_documento !== undefined) {
  const v = {};
  for (const k of ['tipo_documento', ...Object.keys(CAMPOS)]) v[k] = txt(corpo[k]).slice(0, 200);
  const r = conferir(v);
  if (r.erro) return formulario(422, esc(r.erro[0].toUpperCase() + r.erro.slice(1) + '.'), v);
  return [{ json: { acao: 'cadastrar', linha: r.linha, location: '?criado=' + r.linha.id } }];
}

if (q.novo !== undefined) return formulario(200, '', { data_emissao: hoje });
if (q.importar !== undefined) return importar(200, '');

// Documento pronto para o Slides: textos, QR e nome do arquivo; ou o motivo de não dar.
function montar(r) {
  const tipo = txt(r.tipo_documento);
  if (!OBRIGATORIOS[tipo]) return { erro: `tipo de documento desconhecido: "${tipo}"` };
  const faltando = ['data_emissao', ...OBRIGATORIOS[tipo]].filter(k => !txt(r[k]));
  if (faltando.length) return { erro: `falta preencher na planilha: ${faltando.map(k => CAMPOS[k]).join(', ')}` };
  const d = data(r.data_emissao);
  if (!d) return { erro: `data de emissão inválida: "${txt(r.data_emissao)}"` };
  const modelo = tipo === 'certificado_curso' ? MODELO_CERTIFICADO_CURSO
    : tipo.startsWith('certificado_') ? MODELO_CERTIFICADO : MODELO_DECLARACAO;
  if (!modelo || !URL_VALIDACAO || !URL_QR) return { erro: 'modelo, URL de validação ou URL do QR não configurados no n8n' };
  const id = txt(r.id);
  const curso = txt(r.curso);
  const extras = [
    txt(r.dia_aula) && `com aulas semanais (${txt(r.dia_aula)})`,
    txt(r.carga_horaria) && `com carga horária de ${txt(r.carga_horaria)} horas`,
  ].filter(Boolean);
  const textos = tipo.startsWith('certificado_') ? {
    nome: txt(r.nome),
    conclusao: { certificado_curso: 'concluiu o curso de', certificado_semestre: 'concluiu o semestre do curso de',
      certificado_trimestre: 'concluiu o trimestre do curso de' }[tipo],
    CURSO: curso.toUpperCase(),
    carga_horaria: txt(r.carga_horaria),
  } : {
    TITULO: tipo === 'declaracao_matricula' ? 'DECLARAÇÃO DE MATRÍCULA' : 'DECLARAÇÃO DE TÉRMINO DE SEMESTRE',
    abertura: tipo === 'declaracao_matricula' ? 'declara, para os fins que sejam necessários, que' : 'declara que o semestre de',
    NOME: txt(r.nome).toUpperCase(),
    cpf: txt(r.cpf),
    rg: txt(r.rg),
    ENDERECO: txt(r.endereco).toUpperCase(),
    situacao: tipo === 'declaracao_matricula' ? 'está devidamente matriculado(a) no' : 'foi concluído no',
    curso_destaque: tipo === 'declaracao_matricula' ? `curso de ${curso}` : `CURSO DE ${curso.toUpperCase()}`,
    extras: extras.length ? ', ' + extras.join(' e ') : '',
  };
  let estilos = [];
  if (tipo === 'certificado_curso') {
    const pagina = conteudoEmColunas(curso);
    if (pagina.erro) return pagina;
    Object.assign(textos, { curso, conteudo_1: pagina.conteudo_1, conteudo_2: pagina.conteudo_2 });
    estilos = pagina.estilos;
  }
  textos.data = `${d.d} de ${MESES[d.m - 1]} de ${d.a}`;
  textos.id = id;
  // Pedidos para a API do Slides: troca cada {{marcador}} e a caixa {{qr}} pela imagem.
  const requests = Object.entries(textos).map(([k, v]) => ({
    replaceAllText: { containsText: { text: `{{${k}}}`, matchCase: true }, replaceText: v },
  }));
  requests.push(...estilos);
  requests.push({ replaceAllShapesWithImage: {
    containsText: { text: '{{qr}}', matchCase: true },
    imageUrl: `${URL_QR}?id=${id}`,
    imageReplaceMethod: 'CENTER_INSIDE',
  } });
  // Nome do arquivo: "Nome Último-sobrenome - Tipo do documento.pdf", sem controles,
  // invisíveis, aspas nem barras.
  const nomes = txt(r.nome).split(/\s+/);
  const curto = nomes.length > 1 ? `${nomes[0]} ${nomes[nomes.length - 1]}` : nomes[0];
  const arquivo = `${curto} - ${TIPOS[tipo]}`
    .replace(/[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁦-⁩/\\"]/g, '')
    .replace(/\s+/g, ' ').trim() + '.pdf';
  return { doc: { row_number: r.row_number, id, modelo, copia: `Emissão ${id}`, arquivo, requests } };
}
// Segunda página do certificado de curso: itens do curso (sem diferenciar maiúsculas),
// na ordem da aba, com o semestre em maiúsculas como título; divididos em duas
// colunas sem deixar um título sozinho no fim da primeira.
const LINHAS_COLUNA = 26;    // cabem ~26 linhas de 9,5 pt em cada coluna do modelo
const LETRAS_LINHA = 62;     // ~62 caracteres por linha na largura da coluna
function conteudoEmColunas(curso) {
  const itens = conteudos.filter(c => chave(c.curso) === chave(curso) && txt(c.item));
  if (!itens.length) return { erro: `não há conteúdo do curso "${curso}" na aba de conteúdos` };
  const blocos = [];  // [texto, linhas que ocupa, é título]
  let grupo = null;
  for (const c of itens) {
    if (txt(c.semestre) !== grupo) {
      grupo = txt(c.semestre);
      if (blocos.length) blocos.push(['', 1, false]);
      if (grupo) blocos.push([CAIXAS_CONTEUDO.length === 2 ? grupo : grupo.toUpperCase(), 1, true]);
    }
    const t = '•  ' + txt(c.item);
    blocos.push([t, Math.ceil(t.length / LETRAS_LINHA), false]);
  }
  const total = blocos.reduce((n, b) => n + b[1], 0);
  let corte = 0, usadas = 0;
  while (corte < blocos.length && usadas + blocos[corte][1] <= Math.max(Math.ceil(total / 2), 1)) usadas += blocos[corte++][1];
  while (corte > 0 && (blocos[corte - 1][2] || blocos[corte - 1][0] === '')) usadas -= blocos[--corte][1];
  const col1 = blocos.slice(0, corte), col2 = blocos.slice(corte);
  while (col2.length && col2[0][0] === '') col2.shift();
  const linhas = c => c.reduce((n, b) => n + b[1], 0);
  if (linhas(col1) > LINHAS_COLUNA || linhas(col2) > LINHAS_COLUNA) {
    return { erro: `o conteúdo do curso "${curso}" não cabe na segunda página; resuma ou junte itens na aba de conteúdos` };
  }
  const cols = [col1, col2];
  // Títulos em negrito e na cor: faixas de texto de cada caixa, depois da troca dos marcadores.
  const estilos = CAIXAS_CONTEUDO.length !== 2 ? [] : cols.flatMap((col, k) => {
    let pos = 0;
    return col.flatMap(([t, , titulo]) => {
      const ini = pos; pos += t.length + 1;
      return titulo ? [{ updateTextStyle: { objectId: CAIXAS_CONTEUDO[k], fields: 'bold,foregroundColor',
        textRange: { type: 'FIXED_RANGE', startIndex: ini, endIndex: ini + t.length },
        style: { bold: true, foregroundColor: { opaqueColor: { rgbColor: rgb(COR_TITULOS) } } } } }] : [];
    });
  });
  return { conteudo_1: col1.map(b => b[0]).join('\n'), conteudo_2: col2.map(b => b[0]).join('\n'), estilos };
}
const rgb = h => ({ red: parseInt(h.slice(1, 3), 16) / 255, green: parseInt(h.slice(3, 5), 16) / 255,
  blue: parseInt(h.slice(5, 7), 16) / 255 });

const disposicao = arquivo => {
  const ascii = arquivo.normalize('NFD').replace(/[^\x20-\x7e]/g, '');
  return `attachment; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(arquivo)
    .replace(/['()*]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase())}`;
};

// Vários PDFs num ZIP: os documentos marcados na lista, ou um lote do CSV.
if (q.zip !== undefined) {
  const ids = [...new Set([].concat(q.zip).flatMap(v => String(v).split(',')).map(txt).filter(Boolean))];
  if (!ids.length) return lista(422, 'Marque ao menos um documento para baixar.');
  if (ids.length > LIMITE_ZIP) return lista(422, `Marque no máximo ${LIMITE_ZIP} documentos por vez.`);
  const docs = [], erros = [];
  for (const id of ids) {
    const achadas = linhas.filter(l => txt(l.id) === id);
    const m = achadas.length === 1 ? montar(achadas[0]) : { erro: achadas.length ? 'ID duplicado na planilha' : 'documento não encontrado' };
    if (m.erro) erros.push(`${txt((achadas[0] || {}).nome) || id}: ${m.erro}.`); else docs.push(m.doc);
  }
  if (erros.length) return lista(422, 'Nenhum PDF foi gerado:<br>' + erros.map(esc).join('<br>'));
  const repetidos = {};
  for (const doc of docs) {  // nomes iguais no mesmo ZIP ganham um número
    const n = (repetidos[doc.arquivo] = (repetidos[doc.arquivo] || 0) + 1);
    if (n > 1) doc.arquivo = doc.arquivo.replace(/\.pdf$/, ` (${n}).pdf`);
  }
  const zip = `Documentos ${hoje.split('-').reverse().join('-')}.zip`;
  return docs.map(doc => ({ json: { acao: 'zip', ...doc, id_novo: false, disposicao: disposicao(zip) } }));
}

if (!q.id && !q.linha) {
  const extra = {};
  if (txt(q.criado)) {
    const novo = linhas.find(r => txt(r.id) === txt(q.criado));
    if (novo) extra.criado = { nome: esc(novo.nome), href: esc('?id=' + encodeURIComponent(txt(q.criado))) };
  }
  if (txt(q.lote)) {  // depois do CSV: botões para baixar o lote em ZIPs de até LIMITE_ZIP
    const ids = txt(q.lote).split(',').filter(id => linhas.some(r => txt(r.id) === id));
    const zips = partes(ids, LIMITE_ZIP);
    extra.lote = { total: ids.length, zips: zips.map((p, i) => ({ href: esc('?zip=' + p.join(',')),
      rotulo: zips.length > 1 ? `Baixar ZIP ${i + 1} de ${zips.length}` : 'Baixar todos (ZIP)' })) };
  }
  return lista(200, '', extra);
}

// Um PDF: pelo ID (tem de ser único) ou pelo número da linha (sem ID ainda).
let r;
if (q.id) {
  const achadas = linhas.filter(l => txt(l.id) === txt(q.id));
  if (achadas.length !== 1) return lista(404, achadas.length ? 'ID duplicado na planilha.' : 'Documento não encontrado.');
  r = achadas[0];
} else {
  r = linhas.find(l => String(l.row_number) === txt(q.linha));
  if (!r) return lista(404, 'Linha não encontrada.');
}
const erro = m => lista(422, '<strong>Não foi possível gerar o PDF.</strong> ' + esc(`${txt(r.nome) || 'Linha ' + r.row_number}: ${m}.`));
const idNovo = !txt(r.id);
if (idNovo) {
  const id = novoId();
  if (!id) return erro('falha ao gerar o ID; tente de novo');
  r = { ...r, id };
} else if (problema(r)) {
  return erro(problema(r));
}
